def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }
    token_pattern = re.compile(r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[^\s]")

    def integer(text):
        # Chunking also supports literals beyond Python's int-string limit.
        negative = text.startswith("-")
        digits = text[1:] if text[:1] in ("-", "+") else text
        result = 0
        for start in range(0, len(digits), 9):
            chunk = digits[start:start + 9]
            result = result * (10 ** len(chunk)) + int(chunk)
        return -result if negative else result

    def parse(formula):
        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            operator = operators.pop()
            if operator == "neg":
                nodes.append(("neg", nodes.pop()))
            else:
                right = nodes.pop()
                left = nodes.pop()
                if operator == ":":
                    nodes.append(("range", left[1], right[1]))
                else:
                    nodes.append(("binary", operator, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                nodes.append(("number", integer(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = nodes[-count:]
                    del nodes[-count:]
                    if function == "IF":
                        nodes.append(("if", *arguments))
                    else:
                        nodes.append(("function", function, arguments))
                expect_operand = False
            else:
                operator = "neg" if token == "-" and expect_operand else token
                while (
                    operators
                    and operators[-1] in precedence
                    and (
                        precedence[operators[-1]] > precedence[operator]
                        or (
                            precedence[operators[-1]] == precedence[operator]
                            and operator != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(operator)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def argument_nodes(arguments):
        for argument in arguments:
            if argument[0] != "range":
                yield argument
                continue

            first, last = argument[1], argument[2]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))
            for row in range(row1, row2 + 1):
                for column in range(col1, col2 + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def calculate(operator, left, right):
        if operator == "+":
            return left + right
        if operator == "-":
            return left - right
        if operator == "*":
            return left * right
        if operator == "/":
            if right == 0:
                return DIV0
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if operator == "=":
            return left == right
        if operator == "<>":
            return left != right
        if operator == "<":
            return left < right
        if operator == "<=":
            return left <= right
        if operator == ">":
            return left > right
        return left >= right

    results = {}
    active = set()

    for root in cells:
        if root in results:
            continue

        tasks = [("evaluate", ("reference", root))]
        values = []

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "evaluate":
                node = task[1]
                kind = node[0]

                if kind == "number":
                    values.append(node[1])

                elif kind == "reference":
                    name = node[1]
                    if name in results:
                        values.append(results[name])
                    elif name not in cells:
                        values.append(0)
                    elif name in active:
                        values.append(CYCLE)
                    else:
                        content = cells[name].strip()
                        if not content.startswith("="):
                            value = integer(content)
                            results[name] = value
                            values.append(value)
                        else:
                            active.add(name)
                            tasks.append(("finish_cell", name))
                            tasks.append(("evaluate", parse(content[1:])))

                elif kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))

                elif kind == "binary":
                    tasks.append(("left_done", node[1], node[3]))
                    tasks.append(("evaluate", node[2]))

                elif kind == "if":
                    tasks.append(("choose", node[2], node[3]))
                    tasks.append(("evaluate", node[1]))

                elif kind == "function":
                    tasks.append((
                        "next_argument",
                        node[1],
                        argument_nodes(node[2]),
                        None,
                    ))

            elif action == "finish_cell":
                name = task[1]
                results[name] = values[-1]
                active.remove(name)

            elif action == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif action == "left_done":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right_done", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif action == "right_done":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    values.append(calculate(task[1], task[2], right))

            elif action == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    tasks.append((
                        "evaluate",
                        task[1] if condition else task[2],
                    ))

            elif action == "next_argument":
                function, iterator, accumulated = task[1:]
                argument = next(iterator, None)
                if argument is None:
                    values.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append((
                        "argument_done", function, iterator, accumulated,
                    ))
                    tasks.append(("evaluate", argument))

            elif action == "argument_done":
                function, iterator, accumulated = task[1:]
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                if accumulated is None:
                    accumulated = value
                elif function == "SUM":
                    accumulated += value
                elif function == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)

                tasks.append((
                    "next_argument", function, iterator, accumulated,
                ))

    return {name: results[name] for name in cells}
